package ch.bbw.zork;import java.util.Arrays;import java.util.List;/** * Verwaltet die Liste aller gültigen Befehlswörter des Spiels. Der * {@link Parser} fragt hier ab, ob ein eingegebenes Wort ein Befehl ist. */public class CommandWords {	private List<String> validCommands = Arrays.asList(			"continue",			"return",			"back",			"look",			"status",			"map",			"search",			"inventory",			"drop",			"flashlight",			"shop",			"buy",			"use",			"hide",			"unhide",			"peek",			"left",			"right",			"source",			"findbook",			"notes",			"code",			"bandage",			"battery",			"quit",			"help"	);	/**	 * Prüft, ob ein Wort ein gültiges Befehlswort ist.	 *	 * @param commandWord das zu prüfende Wort, bereits in Kleinbuchstaben	 * @return {@code true}, wenn das Wort ein bekannter Befehl ist	 */	public boolean isCommand(String commandWord) {		return validCommands.contains(commandWord);	}	/**	 * Liefert alle gültigen Befehlswörter als einen Text.	 *	 * @return die Befehlswörter, durch Leerzeichen getrennt	 */	public String showAll() {		return String.join(" ", validCommands);	}}